<script setup lang="ts">
import {ref,onMounted,onUnmounted,computed} from 'vue';import {pmsApi} from './api';import {descriptionHtml} from './description';import PmsFormDialog from './PmsFormDialog.vue';
const props=defineProps<{id:number;csrf?:string;userId?:number|null}>();const emit=defineEmits(['close','updated']);const task=ref<any>(null),busy=ref(false),error=ref(''),estimateHours=ref<number|null>(null);let requestVersion=0;let disposed=false;
const percent=computed(()=>task.value?.original_estimate_minutes?Math.round((task.value.time_tracking?.total_seconds||0)/(task.value.original_estimate_minutes*60)*100):0);const color=computed(()=>percent.value>100?'danger':percent.value>=80?'warning':'success');const comments=computed(()=>[...(task.value?.comments||[])].reverse());function hours(minutes:number){return Math.floor(minutes/60)+'h '+minutes%60+'m';}function own(users:any[]){return users?.some(u=>Number(u.id)===Number(props.userId));}function running(sub:any){return sub.timer_logs?.some((l:any)=>Number(l.user_id)===Number(props.userId)&&!l.end_time);}
async function load(){const version=++requestVersion;try{const d=await pmsApi('tasks/'+props.id);if(!disposed&&version===requestVersion){task.value=d.task;estimateHours.value=d.task.original_estimate_minutes?d.task.original_estimate_minutes/60:null;}}catch(e){if(!disposed)error.value=(e as Error).message;}}
async function timer(action:string,sub?:any){if(busy.value)return;busy.value=true;error.value='';try{await pmsApi('timers/'+action,props.csrf,'POST',{task_id:props.id,...(sub?{subtask_id:sub.id}:{})});await load();emit('updated');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function saveEstimate(){busy.value=true;try{await pmsApi('tasks/'+props.id+'/board',props.csrf,'PATCH',{original_estimate_minutes:Number(estimateHours.value)*60});await load();emit('updated');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function changed(){if(!busy.value)void load();}onMounted(()=>{void load();window.addEventListener('pms:changed',changed);});onUnmounted(()=>{disposed=true;window.removeEventListener('pms:changed',changed);});
</script>
<template><PmsFormDialog class="pms-my-work-issue" size="xl" centered title="Issue details" @close="emit('close')"><template #header><div><div class="work-key">ISSUE-{{id}}</div><h5 class="modal-title">{{task?.title||'Issue details'}}</h5></div><button type="button" class="btn btn-sm btn-label-secondary work-modal-close" aria-label="Close" @click="emit('close')"><i class="fa fa-xmark"></i></button></template><p v-if="error" class="notice admin-error">{{error}}</p><div v-if="!task" class="p-4" role="status"><span class="spinner-border spinner-border-sm"></span> Loading issue...</div><div v-else class="row g-0"><div class="col-lg-8 work-details-main"><div class="d-flex flex-wrap gap-2 mb-3"><span class="badge bg-label-primary">{{task.project?.name||'Project'}}</span><span class="badge bg-label-info">{{task.sprint?.name||'Backlog'}}</span><span class="badge" :class="'bg-label-'+(task.workflow_column?.color||'secondary')">{{task.workflow_column?.name||task.status.replaceAll('_',' ')}}</span></div><div class="text-muted" v-html="descriptionHtml(task.description||'No description provided.')"></div><div class="card bg-label-primary border-0 mb-4"><div class="card-body"><div class="d-flex justify-content-between align-items-center"><div><small>TIME TRACKING</small><h5 class="mb-0 mt-1">{{task.time_tracking?.formatted||'0s'}} logged</h5></div><div class="d-flex gap-2"><button v-if="task.directly_assigned_to_me&&task.status!=='completed'" class="btn issue-timer-action" :class="task.own_running_timer?'btn-success':'btn-primary'" :disabled="busy" @click="timer(task.own_running_timer?'stop':'start')"><i class="fa me-1" :class="task.own_running_timer?'fa-stop':'fa-play'"></i>{{task.own_running_timer?'Stop timer':'Start timer'}}</button></div></div><div class="mt-3"><div v-for="u in task.time_tracking?.by_user" :key="u.user_id" class="d-flex justify-content-between py-1"><span>{{u.name}}</span><strong>{{u.formatted}}</strong></div><small v-if="!task.time_tracking?.by_user?.length" class="text-muted">No time logged yet.</small></div><div class="mt-3 pt-3 border-top"><div class="d-flex justify-content-between"><span>Original estimate</span><strong :class="'text-'+color">{{task.original_estimate_minutes?hours(task.original_estimate_minutes):'Not set'}}{{task.original_estimate_minutes?' ('+percent+'%)':''}}</strong></div><div v-if="task.original_estimate_minutes" class="progress mt-2" style="height:7px"><div class="progress-bar" :class="'bg-'+color" :style="{width:Math.min(percent,100)+'%'}"></div></div><small v-for="h in task.estimate_histories?.slice(0,3)" :key="h.id" class="d-block text-muted mt-1">{{h.user?.name||'System'}} set {{hours(h.new_minutes)}}</small><template v-if="task.can_revise_estimate"><form class="input-group mt-3" @submit.prevent="saveEstimate"><input v-model.number="estimateHours" required min="0.25" max="8760" step="0.25" type="number" class="form-control" placeholder="Estimate in hours"><button class="btn btn-outline-primary" :disabled="busy">Save my one revision</button></form><small class="text-muted">You can revise the estimate once.</small></template></div></div></div><h6>Subtasks</h6><div class="list-group mb-4"><div v-for="s in task.subtasks" :key="s.id" class="list-group-item d-flex justify-content-between align-items-center"><div><i class="fa me-2" :class="s.status==='completed'?'fa-circle-check text-success':'fa-circle text-muted'"></i>{{s.title}} <span class="badge bg-label-secondary">{{s.status.replaceAll('_',' ')}}</span></div><button v-if="own(s.users)&&s.status!=='completed'" class="btn btn-sm" :class="running(s)?'btn-outline-success':'btn-outline-primary'" :disabled="busy" :title="running(s)?'Stop timer':'Start timer'" @click="timer(running(s)?'stop':'start',s)"><i class="fa" :class="running(s)?'fa-stop':'fa-play'"></i></button></div><div v-if="!task.subtasks?.length" class="list-group-item text-muted">No subtasks.</div></div><h6>Attachments</h6><div class="list-group mb-4"><a v-for="a in task.attachments" :key="a.id" class="list-group-item list-group-item-action" :href="a.url||'/storage/'+a.path" target="_blank" rel="noopener"><i class="fa fa-paperclip me-2"></i>{{a.original_name}}</a><div v-if="!task.attachments?.length" class="list-group-item text-muted">No attachments.</div></div></div><aside class="col-lg-4 work-comments-panel"><div class="p-3 bg-white border-bottom d-flex justify-content-between align-items-center"><div><h6 class="mb-0"><i class="fa fa-comments me-2 text-primary"></i>Comments</h6><small class="text-muted">Issue conversation</small></div><span class="badge bg-label-primary">{{task.comments?.length||0}}</span></div><div class="work-comments-list"><div v-for="c in comments" :key="c.id" class="work-comment" :class="{'own-comment':Number(c.user_id)===Number(userId)}"><img class="work-comment-avatar" :src="c.user?.profile_img||'/pms-assets/assets/img/user-picture.png'" alt=""><div class="work-comment-content"><div class="work-comment-meta"><span class="work-comment-name">{{c.user?.name||c.author_name||'System'}}</span><span>{{new Date(c.created_at).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}}</span></div><div class="work-comment-bubble">{{c.body}}</div></div></div><div v-if="!comments.length" class="text-center text-muted mt-4"><i class="fa fa-comments mb-2"></i><div>No comments yet.</div></div></div></aside></div><template #footer><a v-if="task?.project_id" :href="'/pms?section=project-board&project='+task.project_id" class="btn btn-label-secondary"><i class="fa fa-arrow-up-right-from-square me-1"></i>Open project board</a><button class="btn btn-primary" @click="emit('close')">Close</button></template></PmsFormDialog></template>
